 public void deleteLibraries(Set<String> names,Runnable done){stopAudition();
  if(!ready||loading||closed||captureBusy()||benchmarkActive()){message="Finalize a gravação, o benchmark ou o carregamento antes de excluir.";changed();if(done!=null)done.run();return;}
  final ArrayList<Bank> targets=new ArrayList<>();for(Bank b:banks)if(names.contains(b.file.getName())&&LibraryEdits.deletable(b.file.getName()))targets.add(b);if(targets.isEmpty()){message="Selecione bibliotecas para excluir. GeneralUser é a biblioteca de segurança.";changed();if(done!=null)done.run();return;}
  final Bank fallback=banks.get(0);loading=true;message="Preparando exclusão de "+targets.size()+" bibliotecas…";changed();worker.execute(()->{try{load(fallback);main.post(()->{
   if(closed)return;try{
    // Only affected channels change; file keys in existing scenes intentionally remain explicit.
    boolean[] affected=new boolean[4];boolean any=false;int nextSolo=solo;for(int ch=0;ch<4;ch++){affected[ch]=targets.contains(banks.get(selectedBank[ch]));if(affected[ch]){any=true;if(solo==ch)nextSolo=-1;}}
    if(any){long[] handles=new long[4];int[] presets=selectedPreset.clone();float[] levels=new float[4];ChannelSettings[] effects=new ChannelSettings[4];for(int ch=0;ch<4;ch++){handles[ch]=affected[ch]?fallback.handle:banks.get(selectedBank[ch]).handle;presets[ch]=affected[ch]?0:selectedPreset[ch];levels[ch]=affected[ch]||muted[ch]||nextSolo>=0&&nextSolo!=ch?0:faderGain[ch];effects[ch]=synth.channels[ch].copy();}synth.replaceScene(handles,presets,levels,effects,synth.voiceLimit,synth.transpose,synth.master,synth.wet,synth.room);if(xyEnabled&&(affected[xyA]||affected[xyB])){xyEnabled=false;synth.armSilent=false;}activeScene="";solo=nextSolo;for(int ch=0;ch<4;ch++)if(affected[ch]){clearSoundComparison(ch);selectedBank[ch]=0;selectedPreset[ch]=0;faderGain[ch]=0;muted[ch]=false;}}
    Set<Integer> removed=new HashSet<>();for(Bank b:targets)removed.add(banks.indexOf(b));int[] mapping=LibraryEdits.mapping(banks.size(),removed);int[] selected=LibraryEdits.selections(selectedBank,mapping,0);System.arraycopy(selected,0,selectedBank,0,4);catalogPinned=-1;
    Set<String> builtins=new HashSet<>(prefs.getStringSet("removedBuiltins",Collections.emptySet()));Set<String> favorites=instrumentFavorites();SharedPreferences.Editor edit=prefs.edit();for(Bank b:targets){if(!LibraryEdits.imported(b.file.getName()))builtins.add(b.file.getName());edit.remove(b.file.getName()).remove(LibraryPedalSettings.key(b.file)).remove("libraryOriginal."+b.file.getName());for(String key:prefs.getAll().keySet())if(key.startsWith("pianoProfile-v1/"+b.file.getName()+"/")||key.startsWith("pianoProfile-v2/"+b.file.getName()+"/"))edit.remove(key);final String prefix=b.file.getName()+"/";favorites.removeIf(key->key.startsWith(prefix));}
    // Persist tombstones before removal so an interrupted deletion is never re-imported on startup.
    Set<String> deleted=new HashSet<>(prefs.getStringSet("deletedLibraries",Collections.emptySet()));for(Bank b:targets)deleted.add(b.file.getName());edit.putStringSet("deletedLibraries",deleted).putStringSet("removedBuiltins",builtins).putStringSet("instrumentFavoritesV1",favorites).apply();banks.removeAll(targets);libraryChanged();for(int ch=0;ch<4;ch++)refreshPianoProfile(ch);applyMix();
    worker.execute(()->{int failures=0;for(Bank b:targets){free(b);if(b.file.exists()&&!b.file.delete())failures++;}final int failed=failures;main.post(()->{if(closed)return;loading=false;cleanup();savePreset(false);message=targets.size()+" bibliotecas excluídas."+(failed>0?" Não foi possível liberar "+failed+" arquivos agora; nova tentativa ao abrir o app.":"")+" Canais afetados ficam em volume 0; cenas antigas exigem reimportar o banco.";changed();if(done!=null)done.run();});});
   }catch(Throwable e){loading=false;applyMix();savePreset(false);message="Exclusão interrompida: "+e.getMessage();changed();if(done!=null)done.run();}
  });}catch(Throwable e){main.post(()->{if(closed)return;loading=false;message="Não foi possível excluir: "+e.getMessage();changed();if(done!=null)done.run();});}});
 }
 public void restoreIncluded(Runnable done){stopAudition();if(!ready||loading||closed)return;loading=true;message="Restaurando bibliotecas incluídas…";changed();worker.execute(()->{try{for(String asset:new String[]{"FluidR3-GM.sf2","YDP-GrandPiano.sf2"})BundledBanks.ensure(asset,getFilesDir(),name->getAssets().open(name));main.post(()->{if(closed)return;Set<String> deleted=new HashSet<>(prefs.getStringSet("deletedLibraries",Collections.emptySet()));for(String asset:new String[]{"FluidR3-GM.sf2","YDP-GrandPiano.sf2"}){deleted.remove(asset);boolean exists=false;for(Bank b:banks)if(b.file.getName().equals(asset))exists=true;if(!exists)banks.add(new Bank(asset.startsWith("Fluid")?"FluidR3 · instrumentos":"YDP · piano de cauda",new File(getFilesDir(),asset)));}prefs.edit().putStringSet("deletedLibraries",deleted).remove("removedBuiltins").apply();libraryChanged();loading=false;message="Bibliotecas incluídas restauradas.";changed();if(done!=null)done.run();});}catch(Throwable e){main.post(()->{if(closed)return;loading=false;message="Restauração falhou: "+e.getMessage();changed();if(done!=null)done.run();});}});}
