 private static void copy(InputStream stream,File file)throws IOException{if(stream==null)throw new IOException("Arquivo indisponível");try(InputStream in=stream;OutputStream out=new FileOutputStream(file)){byte[] b=new byte[65536];long total=0;int n;while((n=in.read(b))!=-1){total+=n;if(total>SfzBank.MAX_SOURCE_BYTES)throw new IOException("Limite de 4 GiB por arquivo importado");if((total&0x3ffffffL)<n)SfzBank.space(file.getParentFile(),64L*1024*1024);out.write(b,0,n);}}}
