 public final MidiHistory history=new MidiHistory();public boolean retrospective,savingRetro;
 public void retrospective(boolean on){if(Synth.retroEnable(on)){retrospective=on;history.enable(on);prefs.edit().putBoolean("retrospective",on).apply();}else message="Memória insuficiente para histórico";changed();}
 public String retroStatus(){long[] v=Synth.retroSnapshot();return !retrospective?"Histórico desativado":v[1]>0?String.format(java.util.Locale.US,"%.1f s disponíveis · áudio final da mesa + MIDI",Math.min(60,Math.min(v[0],8388607L-v[1]*2)/(double)v[1])):"Aguardando áudio";}
 public void saveRetro(int seconds){if(!retrospective||savingRetro)return;long[] v=Synth.retroSnapshot();int rate=(int)v[1];long frames=rate<=0?0:Math.min(v[0],Math.min((long)seconds*rate,8388607L-rate*2L));if(frames<rate){message="Toque por pelo menos um segundo antes de salvar";changed();return;}savingRetro=true;long endMidi=System.nanoTime()/1000,duration=frames*1000000L/rate;java.util.List<MidiTape.Event> midi=history.snapshot(endMidi,duration);File wave=new File(recordingsDir(),"Retro-"+System.currentTimeMillis()+".wav"),mid=new File(recordingsDir(),wave.getName().replace(".wav",".mid"));File wavePending=new File(wave.getPath()+".pending"),midPending=new File(mid.getPath()+".pending");captureStatus="Salvando os últimos "+Math.round(frames/(float)rate)+" s…";changed();worker.execute(()->{try{java.nio.ByteBuffer buffer=java.nio.ByteBuffer.allocateDirect(4096*4).order(java.nio.ByteOrder.LITTLE_ENDIAN);try(java.io.RandomAccessFile out=new java.io.RandomAccessFile(wavePending,"rw")){out.write(WavRecorder.header(frames*4,rate));java.nio.channels.FileChannel channel=out.getChannel();for(long at=0;at<frames;){int n=(int)Math.min(4096,frames-at);if(Synth.retroRead(v[0]-frames+at,(int)v[3],buffer,n)!=n)throw new IOException("Histórico mudou durante a cópia; tente novamente");buffer.position(0);buffer.limit(n*4);while(buffer.hasRemaining())channel.write(buffer);at+=n;}}MidiTape.write(midPending,midi,duration);if(!wavePending.renameTo(wave)||!midPending.renameTo(mid))throw new IOException("Não publicou os arquivos do histórico");main.post(()->{savingRetro=false;recordingRevision++;captureStatus="Histórico salvo: WAV + MIDI";changed();});}catch(Throwable e){wavePending.delete();midPending.delete();wave.delete();mid.delete();main.post(()->{savingRetro=false;captureStatus="Histórico não salvo: "+e.getMessage();changed();});}});}
 public boolean xyEnabled;public int xyA,xyB=1,xyMode;public float xyX=.5f,xyY;
 public void xy(float x,float y){xyX=Math.max(0,Math.min(1,x));xyY=Math.max(0,Math.min(1,y));if(!xyEnabled)return;synth.armSilent=true;synth.armMask=(1<<xyA)|(1<<xyB);faderGain[xyA]=(float)Math.cos(xyX*Math.PI/2);faderGain[xyB]=(float)Math.sin(xyX*Math.PI/2);ChannelSettings a=synth.channels[xyA],b=synth.channels[xyB];if(xyMode==0){a.reverb=b.reverb=Math.round(xyY*150);}else if(xyMode==1){a.high=b.high=Math.round(xyY*12)-6;}else a.chorus=b.chorus=Math.round(xyY*100);synth.channelChange(xyA);synth.channelChange(xyB);applyMix();changed();}
