 private final ChannelSettings[] soundBefore=new ChannelSettings[4],soundAfter=new ChannelSettings[4];private final boolean[] comparingSound=new boolean[4];
 public boolean comparingSound(int ch){return comparingSound[ch];}
 public boolean canCompareSound(int ch){return soundBefore[ch]!=null&&soundAfter[ch]!=null;}
 private void clearSoundComparison(int ch){soundBefore[ch]=soundAfter[ch]=null;comparingSound[ch]=false;}
 public void applySoundPreset(int ch,int id){if(!ready||loading||closed)return;
  if(soundBefore[ch]==null)soundBefore[ch]=synth.channels[ch].copy();
  if(id==0){synth.channels[ch]=soundBefore[ch].copy();comparingSound[ch]=true;}
  else {synth.channels[ch]=PianoSoundPresets.apply(comparingSound[ch]&&soundAfter[ch]!=null?soundAfter[ch]:synth.channels[ch],id);soundAfter[ch]=synth.channels[ch].copy();comparingSound[ch]=false;}
  synth.channelChange(ch);savePreset(false);message="Canal "+(ch+1)+" · "+PianoSoundPresets.NAMES[id];changed();
  if(id>0){float[] p=cachedPianoProfile(ch);if(p==null||p.length<792)preparePianoProfile(ch,null,false);}
 }
 public void compareSound(int ch){if(!ready||loading||closed||soundBefore[ch]==null||soundAfter[ch]==null)return;if(comparingSound[ch]){synth.channels[ch]=soundAfter[ch].copy();comparingSound[ch]=false;}else{soundAfter[ch]=synth.channels[ch].copy();synth.channels[ch]=soundBefore[ch].copy();comparingSound[ch]=true;}synth.channelChange(ch);savePreset(false);changed();}
