 public boolean captureBusy(){return capturing||preparingTake||finishingTake||exportingVideo;}
 public boolean startTake(boolean midi,boolean audioTake,Runnable afterReady){
  if(!ready||loading||captureBusy()||closed||!midi&&!audioTake){message="Aguarde o banco ou finalize a gravação atual.";changed();return false;}
  cancelTune();stopMidi();releasePlayer();resumeAudio();if(!audioTake)wav.error="";if(!midi)tape.warning="";
  preparingTake=true;stopPreparingTake=false;captureStatus="Aguardando saída de áudio…";changed();
  awaitTake(new AudioStartGate(SystemClock.elapsedRealtime()),midi,audioTake,afterReady);return true;
 }
 private void awaitTake(AudioStartGate gate,boolean midi,boolean audioTake,Runnable afterReady){
  if(closed)return;
  if(stopPreparingTake){preparingTake=false;captureStatus="Preparação cancelada";changed();completeTakeCallbacks();return;}
  int state=gate.observe(SystemClock.elapsedRealtime(),synth.isRunning(),synth.audioReady(),synth.sampleRate(),synth.activeBackend());
  if(state==AudioStartGate.WAIT){main.postDelayed(()->awaitTake(gate,midi,audioTake,afterReady),25);return;}
  if(state==AudioStartGate.FAILED){preparingTake=false;captureStatus="A saída não ficou pronta; retome o áudio e tente novamente.";changed();completeTakeCallbacks();return;}
  final int rate=synth.sampleRate();File base=newRecording("");takeMidi=midi?new File(base.getPath()+".mid"):null;
  lastWave=audioTake?new File(base.getPath()+".wav"):null;takeScene=new File(base.getPath()+".scene");
  final File waveFile=lastWave,sceneFile=takeScene;Scene snapshot=scene("Gravação");
  worker.execute(()->{try{
   if(closed)return;if(audioTake)wav.start(waveFile,rate);try(FileWriter out=new FileWriter(sceneFile)){out.write(snapshot.encode());}
   main.post(()->{if(closed){wav.finish();return;}preparingTake=false;capturing=true;captureStartedMs=SystemClock.elapsedRealtime();
    if(midi)tape.start();captureStatus="● Gravando "+(midi&&audioTake?"MIDI + áudio":midi?"MIDI":"áudio");changed();
    if(stopPreparingTake)finishTake(null);else if(afterReady!=null)afterReady.run();
   });
  }catch(Throwable e){wav.finish();main.post(()->{if(!closed){preparingTake=false;captureStatus="Falha ao iniciar: "+e.getMessage();changed();completeTakeCallbacks();}});}});
 }
 private void completeTakeCallbacks(){ArrayList<Runnable> done=new ArrayList<>(takeCallbacks);takeCallbacks.clear();for(Runnable callback:done)callback.run();}
 public void finishTake(Runnable complete){
  if(complete!=null)takeCallbacks.add(complete);
  if(preparingTake){stopPreparingTake=true;return;}
  if(finishingTake)return;
  if(!capturing){completeTakeCallbacks();return;}
  capturing=false;finishingTake=true;tape.stop();captureStatus="Finalizando arquivos…";changed();
  final File midiFile=takeMidi;
  worker.execute(()->{String result="Gravação salva";try{wav.finish();if(midiFile!=null)tape.save(midiFile);
   if(!wav.error.isEmpty())result=wav.error;else if(!tape.warning.isEmpty())result=tape.warning;
  }catch(Throwable e){result="Erro ao finalizar: "+e.getMessage();}
   final String text=result;main.post(()->{finishingTake=false;recordingRevision++;captureStatus=text;changed();completeTakeCallbacks();});
  });
 }
 public File[] recordings(){File[] fs=recordingsDir().listFiles((dir,n)->n.endsWith(".wav")||n.endsWith(".mid")||n.endsWith(".mp4")&&!n.endsWith(".video.mp4"));if(fs==null)return new File[0];Arrays.sort(fs,(a,b)->Long.compare(b.lastModified(),a.lastModified()));return fs;}
 public void playMidi(File file,boolean restoreScene){if(captureBusy()||loading)return;if(restoreScene){File side=new File(file.getPath().replaceAll("\\.mid$",".scene"));try{if(side.exists()){String encoded=new String(java.nio.file.Files.readAllBytes(side.toPath()),java.nio.charset.StandardCharsets.UTF_8);recall(Scene.decode(encoded),()->startMidi(file));return;}}catch(Exception e){captureStatus="Cena da gravação indisponível: "+e.getMessage();changed();return;}}startMidi(file);}
 private void waitMidiScene(File file){if(closed)return;if(loading){main.postDelayed(()->waitMidiScene(file),100);return;}startMidi(file);}
 private void startMidi(File file){stopMidi();releasePlayer();resumeAudio();playingMidi=true;final int token=++playGeneration;captureStatus="▶ MIDI: "+file.getName();changed();midiPlayer=new Thread(()->{try{List<MidiTape.Event> events=MidiTape.read(file);long start=System.nanoTime();for(MidiTape.Event e:events){while(playingMidi&&token==playGeneration){long delay=e.micros*1000-(System.nanoTime()-start);if(delay<=0)break;java.util.concurrent.locks.LockSupport.parkNanos(Math.min(delay,2000000L));}if(!playingMidi||token!=playGeneration)break;int type=e.status&240;if(type==128||type==144||type==176||type==224){int status=type|synth.midiChannel;synth.midi(status,e.a,e.b);history.add(status,e.a,e.b);forwardPiano(status,e.a,e.b);}}}catch(Throwable e){main.post(()->{captureStatus="Reprodução MIDI falhou: "+e.getMessage();changed();});}finally{if(token==playGeneration)playingMidi=false;main.post(()->{if(!closed&&token==playGeneration){synth.panic();cc(synth.midiChannel,64,0);cc(synth.midiChannel,123,0);captureStatus="Reprodução MIDI encerrada";changed();}});}},"PianoMidiPlayer");midiPlayer.start();}
 public void stopMidi(){stopAudition();playGeneration++;playingMidi=false;if(midiPlayer!=null){java.util.concurrent.locks.LockSupport.unpark(midiPlayer);try{midiPlayer.join(200);}catch(InterruptedException e){Thread.currentThread().interrupt();}midiPlayer=null;}if(synth!=null)synth.panic();if(toPiano!=null){cc(synth.midiChannel,64,0);cc(synth.midiChannel,123,0);}}
 private void releasePlayer(){if(player!=null){player.release();player=null;}}
 public void stopPlayback(){stopMidi();releasePlayer();if(!closed&&ready)resumeAudio();captureStatus="Reprodução parada";changed();}
 public void playWave(File file){if(captureBusy())return;stopMidi();releasePlayer();synth.stop();try{player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(file.getAbsolutePath());AudioDeviceInfo output=findRoute();if(output!=null)player.setPreferredDevice(output);player.setOnPreparedListener(p->{p.start();captureStatus="▶ Áudio: "+file.getName();changed();});player.setOnCompletionListener(p->{releasePlayer();resumeAudio();captureStatus="Reprodução de áudio encerrada";changed();});player.setOnErrorListener((p,a,b)->{releasePlayer();resumeAudio();captureStatus="Falha na reprodução de áudio";changed();return true;});player.prepareAsync();}catch(Exception e){releasePlayer();resumeAudio();captureStatus=e.getMessage();changed();}}
 public interface CatalogResult {void loaded(java.util.List<InstrumentIndex.Entry> entries,String warning);}
 /** Snapshot bank files on main; index headers on the worker, without loading samples. */
 public void generalCatalog(CatalogResult done){
  if(cachedCatalog!=null&&cachedRevision==libraryRevision){done.loaded(cachedCatalog,cachedWarning);return;}
  final int version=libraryRevision;final ArrayList<Bank> snapshot=new ArrayList<>(banks);
  worker.execute(()->{ArrayList<InstrumentIndex.Entry> entries=new ArrayList<>();StringBuilder warnings=new StringBuilder();for(int i=0;i<snapshot.size();i++){if(closed)return;Bank b=snapshot.get(i);try{entries.addAll(InstrumentIndex.read(b.file,b.name,i,b.originalName));}catch(IOException e){if(warnings.length()>0)warnings.append("; ");warnings.append(b.name).append(": ").append(e.getMessage());}}final String warning=warnings.toString();final List<InstrumentIndex.Entry> result=Collections.unmodifiableList(entries);main.post(()->{if(closed)return;if(version!=libraryRevision){generalCatalog(done);return;}cachedCatalog=result;cachedWarning=warning;cachedRevision=version;done.loaded(result,warning);});});
 }
