 /** Keep the old voice graph playing while loading only the bank actually chosen. */
 public interface InstrumentChoice {void complete(boolean ok,String detail);}
 public void chooseInstrument(int layer,InstrumentIndex.Entry entry,InstrumentChoice done){stopAudition();
  if(!ready||loading||closed||layer<0||layer>=4||entry.source<0||entry.source>=banks.size())return;
  if(selectedBank[layer]==entry.source&&selectedPreset[layer]==entry.preset){if(done!=null)done.complete(true,entry.name);return;}
  Bank b=banks.get(entry.source);if(!entry.key.startsWith(b.file.getName()+"/")){if(done!=null)done.complete(false,"A biblioteca mudou; abra a lista novamente.");return;}loading=true;message="Carregando "+entry.name+"…";changed();
  worker.execute(()->{try{load(b);main.post(()->{if(closed){free(b);return;}loading=false;
   if(entry.preset<0||entry.preset>=b.names.length){message="Preset não encontrado no banco";changed();if(done!=null)done.complete(false,message);return;}
   selectInstrument(layer,entry.source,entry.preset);if(done!=null)done.complete(selectedBank[layer]==entry.source&&selectedPreset[layer]==entry.preset,message);
  });}catch(Throwable e){main.post(()->{if(!closed){loading=false;message="Não abriu o instrumento: "+e.getMessage();changed();if(done!=null)done.complete(false,message);}});}});
 }
 public void catalogBank(int index,Runnable done){if(loading||index<0||index>=banks.size())return;catalogPinned=index;Bank b=banks.get(index);if(b.handle!=0){done.run();return;}loading=true;changed();worker.execute(()->{try{load(b);main.post(()->{if(closed){free(b);return;}loading=false;done.run();changed();});}catch(Throwable e){main.post(()->{if(!closed){loading=false;message="Não abriu o banco: "+e.getMessage();changed();}});}});}
 public void selectInstrument(int layer,int bank,int preset){if(!ready||loading||selectedBank[layer]==bank&&selectedPreset[layer]==preset)return;Bank b=banks.get(bank);if(b.handle==0||preset<0||preset>=b.names.length)return;try{clearSoundComparison(layer);synth.setLayer(layer,b.handle,preset);selectedBank[layer]=bank;selectedPreset[layer]=preset;refreshPianoProfile(layer);cleanup();savePreset(false);message=b.display[preset];}catch(Throwable e){message="Não trocou o timbre: "+e.getMessage();}changed();}
 public void releaseCatalog(){catalogPinned=-1;if(!loading)cleanup();}
