 public boolean fileBusy(File file){return captureBusy()||mediaBusy.contains(file.getAbsolutePath());}
 public boolean deletingAllowed(File file){return !fileBusy(file)&&!playingMidi&&player==null;}
 public void deleteRecording(File file,Runnable done){
  if(!deletingAllowed(file)){captureStatus="Finalize a gravação ou reprodução antes de excluir.";changed();return;}
  mediaBusy.add(file.getAbsolutePath());worker.execute(()->{String result;try{RecordingFiles.delete(recordingsDir(),file);result="Gravação excluída do aplicativo";}catch(Exception e){result=e.getMessage();}
   final String text=result;main.post(()->{mediaBusy.remove(file.getAbsolutePath());resolveGallery(file);recordingRevision++;captureStatus=text;changed();if(done!=null)done.run();});
  });
 }
 private void queueGallery(File file){String pending=prefs.getString("pendingGallery","");String item=file.getName()+"\n";if(!pending.contains(item))prefs.edit().putString("pendingGallery",pending+item).apply();}
 public void resolveGallery(File file){String pending=prefs.getString("pendingGallery","");prefs.edit().putString("pendingGallery",pending.replace(file.getName()+"\n","")).apply();}
 public File pendingGallery(){for(String name:prefs.getString("pendingGallery","").split("\n")){if(name.isEmpty())continue;File file=new File(recordingsDir(),name);try{RecordingFiles.require(recordingsDir(),file);if(name.endsWith(".mp4")&&!fileBusy(file))return file;}catch(IOException e){resolveGallery(file);}}return null;}
 public void saveGallery(File file,Runnable done){
  if(fileBusy(file)){captureStatus="Aguarde o arquivo terminar de salvar.";changed();return;}
  mediaBusy.add(file.getAbsolutePath());captureStatus="Salvando na galeria…";changed();
  worker.execute(()->{String result;try{RecordingFiles.require(recordingsDir(),file);if(!file.getName().endsWith(".mp4"))throw new IOException("A galeria recebe vídeos MP4");
   String key="gallery:"+file.getName(),existing=prefs.getString(key,"");
   if(!GalleryExporter.exists(getContentResolver(),existing)){Uri uri=GalleryExporter.save(getContentResolver(),file);prefs.edit().putString(key,uri.toString()).apply();}
   result="Vídeo na galeria · álbum Piano Universe";
  }catch(Exception e){result="Não foi possível salvar na galeria: "+e.getMessage();}
   final String text=result;main.post(()->{mediaBusy.remove(file.getAbsolutePath());recordingRevision++;captureStatus=text;changed();if(done!=null)done.run();});
  });
 }
