 public void saveMidiEdit(MidiEdit model){File file=new File(recordingsDir(),"Editado-"+System.currentTimeMillis()+".mid");File pending=new File(file.getPath()+".pending");java.util.List<MidiTape.Event> events=model.export();worker.execute(()->{try{MidiTape.write(pending,events,model.duration);if(!pending.renameTo(file))throw new IOException("Não publicou MIDI editado");main.post(()->{recordingRevision++;captureStatus="MIDI editado salvo como nova cópia";changed();});}catch(Exception e){pending.delete();file.delete();main.post(()->{captureStatus="Não salvou MIDI: "+e.getMessage();changed();});}});}
 public void exportFile(Uri uri,File file){if(fileBusy(file)){captureStatus="Finalize a gravação antes de exportar.";changed();return;}mediaBusy.add(file.getAbsolutePath());worker.execute(()->{String result;try{RecordingFiles.require(recordingsDir(),file);try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Destino indisponível");byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}result="Arquivo exportado: "+file.getName();}catch(Exception e){result="Exportação falhou: "+e.getMessage();}final String text=result;main.post(()->{mediaBusy.remove(file.getAbsolutePath());captureStatus=text;changed();});});}
 public void importScenes(Uri uri){worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Arquivo indisponível");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>131072)throw new IOException("Template excessivo");}org.json.JSONObject root=new org.json.JSONObject(new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));if(!"Piano-Room-scenes".equals(root.getString("format"))||root.getInt("version")!=1)throw new IOException("Formato de template incompatível");org.json.JSONArray items=root.getJSONArray("scenes");if(items.length()>12)throw new IOException("Máximo de 12 cenas");ArrayList<Scene> imported=new ArrayList<>();for(int i=0;i<items.length();i++)imported.add(Scene.decode(items.getJSONObject(i).getString("data")));main.post(()->{int added=0;SharedPreferences.Editor e=prefs.edit();for(int slot=0;slot<12&&added<imported.size();slot++)if(sceneAt(slot)==null){try{e.putString("scene"+slot,imported.get(added).encode());added++;}catch(IOException ignored){}}e.apply();sceneRevision++;message=added+" cenas importadas"+(added<imported.size()?". Sem espaço para as restantes; libere cenas e tente novamente.":".");changed();});}catch(Exception e){main.post(()->{message="Importação de templates falhou: "+e.getMessage();changed();});}});}
