 public static String midiName(MidiDeviceInfo d){String n=d.getProperties().getString(MidiDeviceInfo.PROPERTY_NAME);if(n==null)n=d.getProperties().getString(MidiDeviceInfo.PROPERTY_PRODUCT);return n==null?"Piano USB":n;}
 private static String fingerprint(MidiDeviceInfo d){Bundle p=d.getProperties();return p.getString(MidiDeviceInfo.PROPERTY_MANUFACTURER,"")+"|"+p.getString(MidiDeviceInfo.PROPERTY_PRODUCT,"")+"|"+p.getString(MidiDeviceInfo.PROPERTY_NAME,"")+"|"+p.getString(MidiDeviceInfo.PROPERTY_SERIAL_NUMBER,"");}
 public ArrayList<MidiDeviceInfo> midiDevices(){ArrayList<MidiDeviceInfo> ds=new ArrayList<>();if(manager!=null)for(MidiDeviceInfo d:manager.getDevices())if(d.getType()==MidiDeviceInfo.TYPE_USB&&d.getOutputPortCount()>0)ds.add(d);return ds;}
 public void connect(MidiDeviceInfo info){if(!ready){message="Aguarde a biblioteca.";changed();return;}closeMidi(true);midiTarget=fingerprint(info);prefs.edit().putString("midiTarget",midiTarget).putBoolean("autoReconnect",true).apply();reconnect.enable();waitForMidi=true;open(info);}
 private void open(MidiDeviceInfo info){int token=reconnect.begin();if(token<0)return;midiStatus="Abrindo "+midiName(info)+"…";changed();try{manager.openDevice(info,d->{
  if(closed||!reconnect.current(token)){closeDevice(d);return;}
  if(d==null){reconnect.finish(token,false);midiStatus="Porta indisponível · tentando reconectar";scheduleReconnect();changed();return;}
  MidiOutputPort out=null;MidiInputPort in=null;
  for(MidiDeviceInfo.PortInfo p:info.getPorts()){if(p.getType()==MidiDeviceInfo.PortInfo.TYPE_OUTPUT&&out==null)out=d.openOutputPort(p.getPortNumber());if(p.getType()==MidiDeviceInfo.PortInfo.TYPE_INPUT&&in==null)in=d.openInputPort(p.getPortNumber());}
  if(out==null||in==null){try{if(out!=null)out.close();if(in!=null)in.close();}catch(IOException ignored){}closeDevice(d);reconnect.finish(token,false);midiStatus="Porta MIDI ocupada. Feche outros apps; nova tentativa automática.";scheduleReconnect();changed();return;}
  device=d;fromPiano=out;toPiano=in;reconnect.finish(token,true);main.removeCallbacks(retry);parser.reset();final MidiDevice expected=d;fromPiano.connect(new MidiReceiver(){@Override public void onSend(byte[] bytes,int offset,int length,long timestamp){if(!closed&&device==expected){midiBytes.addAndGet(length);synth.receivedAt(timestamp);parser.accept(bytes,offset,length);}}});waitForMidi=false;midiStatus="USB conectado · "+midiName(info);remote.reset();remote.probe();if(integrated)configureHardware();decisionPending=!prefs.getBoolean("yamahaChoice",false);updatePlayback();message="Conexão pronta; continuará em segundo plano.";changed();
 },main);}catch(RuntimeException e){reconnect.finish(token,false);midiStatus="Abertura MIDI falhou: "+e.getMessage();scheduleReconnect();changed();return;}
 // A stalled Android callback must not permanently block all future reconnects.
 main.postDelayed(()->{if(!closed&&reconnect.current(token)){reconnect.lost();midiStatus="O Android não concluiu a abertura; tentando novamente.";scheduleReconnect();changed();}},5000);
 }
 private static void closeDevice(MidiDevice d){if(d!=null)try{d.close();}catch(IOException ignored){}}
 private void scheduleReconnect(){main.removeCallbacks(retry);if(!closed&&reconnect.enabled())main.postDelayed(retry,reconnect.nextDelay());}
 private final Runnable retry=()->tryReconnect();
 private void tryReconnect(){if(closed||!ready||!reconnect.enabled()||device!=null||reconnect.opening())return;MidiDeviceInfo match=null;for(MidiDeviceInfo d:midiDevices())if(fingerprint(d).equals(midiTarget)){if(match!=null){midiStatus="Dois dispositivos iguais. Escolha o piano na tela.";changed();scheduleReconnect();return;}match=d;}if(match!=null)open(match);else{midiStatus="Aguardando o piano · reconexão automática";changed();scheduleReconnect();}}
 public void disconnect(){reconnect.disable();main.removeCallbacks(retry);prefs.edit().putBoolean("autoReconnect",false).apply();closeMidi(true);waitForMidi=false;midiStatus="Desconectado por você · reconexão pausada";updatePlayback();changed();}
 private void closeMidi(boolean restore){stopAudition();pauseYamahaAudio();yamahaLoopbackOff=false;if(restore)restorePiano(false);else{echoPiano=false;localChanged=masterChanged=pianoChanged=false;}if(synth!=null)synth.panic();if(parser!=null)parser.reset();synchronized(midiWriteLock){try{if(fromPiano!=null)fromPiano.close();}catch(IOException ignored){}try{if(toPiano!=null)toPiano.close();}catch(IOException ignored){}closeDevice(device);fromPiano=null;toPiano=null;device=null;}if(remote!=null)remote.reset();decisionPending=false;}
 private final MidiManager.DeviceCallback midiCallback=new MidiManager.DeviceCallback(){
  @Override public void onDeviceAdded(MidiDeviceInfo info){if(reconnect.enabled()){main.removeCallbacks(retry);tryReconnect();}}
  @Override public void onDeviceRemoved(MidiDeviceInfo info){if(device!=null&&device.getInfo().getId()==info.getId()||reconnect.opening()&&fingerprint(info).equals(midiTarget)){cancelTune();closeMidi(false);reconnect.lost();waitForMidi=true;synth.stop();setWake(false);midiStatus="Piano desconectou · aguardando reconexão";message="Sessão e volumes preservados.";scheduleReconnect();changed();}}
 };
 public boolean connected(){return device!=null;}
 private boolean sendMidi(byte[] bytes){synchronized(midiWriteLock){if(toPiano==null)return false;try{toPiano.send(bytes,0,bytes.length);return true;}catch(IOException e){return false;}}}
 private boolean cc(int ch,int c,int v){return sendMidi(new byte[]{(byte)(176|ch),(byte)c,(byte)v});}
 private void sendAll(int c,int v){for(int ch=0;ch<16;ch++)cc(ch,c,v);}
 private void forwardPiano(int s,int a,int b){if(!echoPiano||closed||(s&15)!=synth.midiChannel)return;int k=s&240;if(k==144||k==128||k==224||k==176&&(a==64||a==66||a==67||a==120||a==123))synchronized(midiWriteLock){echoMessage[0]=(byte)s;echoMessage[1]=(byte)a;echoMessage[2]=(byte)b;sendMidi(echoMessage);}}
 public void chooseYamaha(boolean mute){decisionPending=false;prefs.edit().putBoolean("yamahaChoice",true).putBoolean("yamahaCompact",true).putBoolean("connectionCompact",true).apply();integrated=true;pianoMode=1;pianoVolume=mute?0:127;saveHardware();configureHardware();changed();}
 public void enableHardware(boolean on){if(!on)restorePiano(false);integrated=on;saveHardware();if(on)configureHardware();changed();}
 public void mode(int value){restorePiano(false);pianoMode=value;saveHardware();if(integrated)configureHardware();changed();}
 private void saveHardware(){decisionPending=false;if(pianoVolume>0)yamahaRemembered=pianoVolume;prefs.edit().putInt("yamahaRemembered",yamahaRemembered).apply();prefs.edit().putBoolean("yamahaChoice",true).putBoolean("yamahaEnabled",integrated).putInt("yamahaMode",pianoMode).putInt("yamahaVolume",pianoVolume).putInt("yamahaReverb",pianoReverb).apply();}
 public void probe(){if(toPiano==null){hardwareStatus="Abra a conexão MIDI primeiro.";changed();return;}remote.probe();}
 private void configureHardware(){if(toPiano==null||focusLost)return;int volume=YamahaMixer.effective(pianoVolume,solo);yamahaMixSent=volume;if(pianoMode==0){echoPiano=false;remote.probe();hardwareStatus="Consultando parâmetros SysEx. Alterações exigem resposta do piano.";}else if(pianoMode==1){localChanged=pianoChanged=true;sendAll(122,0);cc(synth.midiChannel,7,volume);cc(synth.midiChannel,91,pianoReverb);echoPiano=true;hardwareStatus=volume==0?"Som interno silenciado por MIDI · sons do app ativos":"Local Off + retorno MIDI · Yamaha em "+volume+"/127";}else{echoPiano=false;masterChanged=true;sendMidi(YamahaProtocol.masterVolume(volume));hardwareStatus="Master Volume enviado · confira o resultado no piano.";}changed();}
 public void hardware(int volume,int reverb){if(volume>=0)pianoVolume=Math.max(0,Math.min(127,volume));if(reverb>=0)pianoReverb=Math.max(0,Math.min(127,reverb));saveHardware();if(!integrated){hardwareStatus="Ative a integração para enviar este ajuste.";changed();return;}int target=volume<0?-1:YamahaMixer.effective(pianoVolume,solo);if(target>=0)yamahaMixSent=target;queueHardware(target,reverb<0?-1:pianoReverb);}
 private void syncYamahaMix(){if(!integrated)return;int target=YamahaMixer.effective(pianoVolume,solo);if(target!=yamahaMixSent){yamahaMixSent=target;queueHardware(target,-1);}}
 private void queueHardware(int volume,int reverb){if(volume>=0)pendingVolume=volume;if(reverb>=0)pendingReverb=reverb;if(controlsQueued)return;controlsQueued=true;main.postDelayed(()->{controlsQueued=false;int v=pendingVolume,r=pendingReverb;pendingVolume=pendingReverb=-1;if(closed||!integrated||toPiano==null)return;if(v>=0)v=YamahaMixer.effective(pianoVolume,solo);if(pianoMode==0){if(v>=0)remote.volume(v);if(r>=0)remote.reverb(r);}else if(pianoMode==1){if(v>=0){pianoChanged=true;cc(synth.midiChannel,7,v);}if(r>=0)cc(synth.midiChannel,91,r);hardwareStatus="Yamaha · volume "+YamahaMixer.effective(pianoVolume,solo)+"/127 · retorno MIDI ativo";}else if(v>=0){masterChanged=true;sendMidi(YamahaProtocol.masterVolume(v));}changed();},40);}
 public void yamahaFader(int percent){int v=YamahaMixer.fromPercent(percent);if(!integrated){pianoVolume=v;enableHardware(true);}hardware(v,-1);}
 public void yamahaMute(){int v=pianoVolume==0?Math.max(1,yamahaRemembered):0;if(!integrated){pianoVolume=v;enableHardware(true);}hardware(v,-1);}
 public void yamahaSolo(){if(!integrated)enableHardware(true);solo(YamahaMixer.CHANNEL);}
 public void restore(){restorePiano(true);integrated=false;pianoVolume=127;saveHardware();hardwareStatus="Restauração solicitada · som original do Yamaha";changed();}
 private void restorePiano(boolean force){echoPiano=false;yamahaMixSent=-1;pendingVolume=pendingReverb=-1;if(remote!=null)remote.restore(force);if(localChanged||force){sendAll(64,0);sendAll(123,0);sendAll(122,127);}if(pianoChanged||force)sendAll(7,127);if(masterChanged||force)sendMidi(YamahaProtocol.masterVolume(127));localChanged=masterChanged=pianoChanged=false;}
 public void yamahaVoice(int p){if(!integrated||toPiano==null)return;int[] l={0,2,1,0,1,0,0,0,118,0},pg={0,1,4,5,19,19,6,21,73,48};if(pianoMode==0)remote.voice((108<<16)|(l[p]<<8)|pg[p]);else if(pianoMode==1){cc(synth.midiChannel,0,108);cc(synth.midiChannel,32,l[p]);sendMidi(new byte[]{(byte)(192|synth.midiChannel),(byte)pg[p]});}}
 public void channel(int channel){restorePiano(false);synth.panic();synth.midiChannel=channel;parser.reset();if(integrated)configureHardware();savePreset(false);changed();}

 public ArrayList<AudioDeviceInfo> outputs(){ArrayList<AudioDeviceInfo> ds=new ArrayList<>();ds.add(null);for(AudioDeviceInfo d:audio.getDevices(AudioManager.GET_DEVICES_OUTPUTS)){int t=d.getType();if(t==AudioDeviceInfo.TYPE_USB_DEVICE||t==AudioDeviceInfo.TYPE_USB_HEADSET||t==AudioDeviceInfo.TYPE_BLUETOOTH_A2DP||t==AudioDeviceInfo.TYPE_WIRED_HEADPHONES||t==AudioDeviceInfo.TYPE_WIRED_HEADSET||t==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER)ds.add(d);}return ds;}
 public static String audioType(int t){if(t==AudioDeviceInfo.TYPE_USB_DEVICE||t==AudioDeviceInfo.TYPE_USB_HEADSET)return "USB";if(t==AudioDeviceInfo.TYPE_BLUETOOTH_A2DP)return "Bluetooth · maior atraso";if(t==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER)return "Celular";return "Fone com fio";}
 public int selectedOutput(ArrayList<AudioDeviceInfo> ds){for(int i=1;i<ds.size();i++)if(ds.get(i).getType()==routeType&&ds.get(i).getProductName().toString().equals(routeName))return i;return 0;}
 public void output(AudioDeviceInfo d){stopAudition();pauseYamahaAudio();stopBenchmark("Troca de saída.");if(captureBusy()){message="Finalize a gravação antes de trocar a saída.";changed();return;}cancelTune();routeType=d==null?-1:d.getType();routeName=d==null?"":d.getProductName().toString();prefs.edit().putBoolean("routeChosen",true).putInt("routeType",routeType).putString("routeName",routeName).apply();routeId=-1;updatePlayback();changed();}
