 public String auditionStatus="Escolha um canal e ouça o hino com o timbre atual.";
 public boolean auditionActive(){return auditionPending||auditionPlayer!=null;}
 public void stopAudition(){
  if(!auditionActive())return;auditionGeneration++;auditionPending=false;AuditionPlayer old=auditionPlayer;auditionPlayer=null;
  if(old!=null){old.cancel();try{old.join(200);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
  playingMidi=false;if(synth!=null){synth.panic();if(auditionMixed){float[] levels=new float[4];for(int i=0;i<4;i++)levels[i]=muted[i]||solo>=0&&solo!=i?0:faderGain[i];synth.setGains(levels);synth.metro=auditionMetro;synth.change();}}auditionMixed=false;auditionStatus="Demonstração parada · volumes restaurados.";
 }
 public void audition(int channel,boolean hymn,String notes,int tempo,int speed,boolean pedal){
  if(channel<0||channel>3||!ready||loading||closed||captureBusy()||benchmarkActive()){message="Finalize o carregamento, a gravação ou o benchmark antes de ouvir.";changed();return;}
  stopMidi();releasePlayer();cancelTune();pauseYamahaAudio();auditionPending=true;final int token=++auditionGeneration;resumeAudio();auditionStatus="Preparando demonstração…";changed();
  worker.execute(()->{try{
   AuditionSequence plan;
   if(hymn){File file=new File(getCacheDir(),"santo-santo-santo-demo.mid");try(InputStream in=getAssets().open("demo/santo-santo-santo.mid");OutputStream out=new FileOutputStream(file)){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}plan=AuditionSequence.midi(MidiTape.read(file),speed);}
   else plan=AuditionSequence.notes(notes,tempo,88,pedal);
   final AuditionSequence readyPlan=plan;main.post(()->{if(closed||token!=auditionGeneration)return;auditionPending=false;playingMidi=true;auditionMetro=synth.metro;synth.metro=false;synth.change();synth.panic();float[] levels=new float[4];levels[channel]=.65f;synth.setGains(levels);auditionMixed=true;
    auditionStatus=(hymn?"Santo! Santo! Santo!":"Sua sequência")+" · canal "+(channel+1)+" · "+banks.get(selectedBank[channel]).name;
    auditionPlayer=new AuditionPlayer(readyPlan,new AuditionPlayer.Sink(){public boolean ready(){return !closed&&token==auditionGeneration&&synth.audioReady();}public void event(int type,int key,int value){if(!closed&&token==auditionGeneration)synth.auditionEvent(channel,type,key,value);}public void finished(String error){main.post(()->{if(closed||token!=auditionGeneration)return;stopAudition();auditionStatus=error.isEmpty()?"Demonstração concluída · volumes restaurados.":error;changed();});}});auditionPlayer.start();changed();});
  }catch(Exception e){main.post(()->{if(!closed&&token==auditionGeneration){stopAudition();auditionStatus="Não foi possível tocar: "+e.getMessage();message=auditionStatus;changed();}});}});
 }
