 private void updatePlayback(){if(closed||!ready||synth==null)return;if(player!=null){routeStatus="Reprodução do áudio gravado";return;}
  if(device!=null&&routeType<0&&!prefs.getBoolean("routeChosen",false)){AudioDeviceInfo usb=null;for(AudioDeviceInfo d:outputs())if(d!=null&&(d.getType()==AudioDeviceInfo.TYPE_USB_DEVICE||d.getType()==AudioDeviceInfo.TYPE_USB_HEADSET)){if(usb!=null){usb=null;break;}usb=d;}if(usb!=null){routeType=usb.getType();routeName=usb.getProductName().toString();prefs.edit().putInt("routeType",routeType).putString("routeName",routeName).apply();}}
  synth.availableDevices(audio.getDevices(AudioManager.GET_DEVICES_OUTPUTS));AudioDeviceInfo desired=findRoute();boolean missing=routeType>=0&&desired==null;
  if(waitForMidi&&!auditionActive()||missing||focusLost){stopBenchmark("Saída indisponível ou foco perdido.");synth.stop();setWake(false);routeStatus=missing?"Saída escolhida ausente · aguardando reconexão":focusLost?"Pausado por foco de áudio":"Aguardando piano";return;}
  int id=desired==null?-1:desired.getId();if(id!=routeId){stopBenchmark("Rota de áudio mudou.");cancelTune();synth.stop();routeId=id;synth.preferred(desired);}
  if(!focusHeld){focusHeld=audio.requestAudioFocus(focusRequest)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;if(!focusHeld){routeStatus="Foco de áudio indisponível · toque Retomar áudio";setWake(false);return;}}
  synth.start();setWake(true);AudioDeviceInfo effective=synth.routed();routeStatus=effective==null?"Áudio iniciando…":effective.getProductName()+" · "+audioType(effective.getType());
 }
