 public PianoBenchmark benchmark;private Scene benchmarkBefore;private int benchmarkProfile,benchmarkManual,benchmarkRoute;private boolean benchmarkAdaptive,benchmarkProtect,benchmarkArm,benchmarkMetro,benchmarkEq;public String benchmarkReport="";public int benchmarkRecommended=-1;private String benchmarkRouteKey="";
