 private String benchmarkEnvironment(){
  android.os.PowerManager pm=(android.os.PowerManager)getSystemService(POWER_SERVICE);
  android.content.Intent battery=registerReceiver(null,new android.content.IntentFilter(android.content.Intent.ACTION_BATTERY_CHANGED));
  android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();((android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(memory);
  android.os.Debug.MemoryInfo process=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(process);
  long[] bankMem=synth.bankMemory();
  String ram="RAM total/disponível bytes: "+memory.totalMem+"/"+memory.availMem+" / pouca RAM: "+memory.lowMemory+" / heap nativo alocado bytes: "+android.os.Debug.getNativeHeapAllocatedSize()+" / PSS processo KiB: "+process.getTotalPss()+" / samples únicos bytes: "+bankMem[0]+" / pré-aquecidos no carregamento bytes: "+bankMem[1]+" / mapeados bytes: "+bankMem[2]+" / "+synth.performanceDetails();
  return ram+" / Motor: "+Synth.backendName(synth.activeBackend())+" / Paralelo: "+java.util.Arrays.toString(Synth.parallelStats())+" / Tela ligada: "+pm.isInteractive()+" / economia: "+pm.isPowerSaveMode()+" / térmico Android: "+(Build.VERSION.SDK_INT>=29?pm.getCurrentThermalStatus():-1)+" / bateria temperatura (décimos °C): "+(battery==null?-1:battery.getIntExtra("temperature",-1))+" / memória Java usada: "+(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory())+" / "+synth.audioDetails()+" / fallback: "+synth.fallbackReason;
 }
 private void diagnosticPhase(int phase){
  if(phase>=6)return;
  synth.soundEq=phase==5&&benchmarkEq;synth.soundChange();
  synth.panic();synth.master=Math.min(.65f,benchmarkBefore.master);synth.wet=phase==5?benchmarkBefore.wet:0;
  float[] gains=new float[4];for(int ch=0;ch<3;ch++)gains[ch]=(phase>=3||phase==ch)?.28f:0;synth.setGains(gains);
  for(int ch=0;ch<4;ch++){ChannelSettings c=phase==5?benchmarkBefore.effects[ch].copy():new ChannelSettings();if(phase<5){c.reverb=0;c.chorus=phase==4?15:0;}synth.channels[ch]=c;}synth.change();
 }
 private void startBenchmark(boolean diagnostic,boolean capacityTest){
  if(yamahaUsbWanted){message="Pause os efeitos USB Yamaha antes do benchmark de bibliotecas.";changed();return;}
  if(closed||!ready||loading||captureBusy()||playingMidi||player!=null){message="Finalize carregamento ou gravação antes do benchmark.";changed();return;}if(benchmarkActive())return;
  if(!synth.isRunning()||!synth.audioReady()){message="Inicie o áudio antes do benchmark.";changed();return;}cancelTune();savePreset(false);
  benchmarkBefore=scene("Antes do benchmark");benchmarkProfile=synth.latencyProfile();benchmarkManual=synth.manualBuffer();benchmarkAdaptive=synth.automaticBuffer();benchmarkProtect=synth.protectedOutput();benchmarkRoute=routeId;benchmarkRouteKey=benchmarkKey();benchmarkArm=synth.armSilent;benchmarkMetro=synth.metro;benchmarkEq=synth.soundEq;synth.metro=false;synth.armSilent=false;
  if(diagnostic){
   final String context="Iniciado: "+new java.util.Date()+"\n"+diagnostic()+"\n"+benchmarkEnvironment();
   final int fixedBuffer=Math.max(2,Math.min(120,(int)Math.ceil(synth.acceptedBufferMs())));
   synth.automaticBuffer(false);synth.protectedOutput(true);
   DiagnosticBenchmark.DiagnosticDriver diagnosticDriver=new DiagnosticBenchmark.DiagnosticDriver(){
    public void buffer(int ms){synth.latencyProfile(2);synth.manualBuffer(ms);synth.benchmarkMetrics();}
    public void midi(int type,int key,int value){synth.midi(type|synth.midiChannel,key,value);}
    public PianoBenchmark.Metrics metrics(){return synth.benchmarkMetrics();}
    public int voices(){int total=0;int[] v=synth.voicesNow();for(int i=0;i<4;i++)total+=v[i];return total;}
    public void phase(int n){diagnosticPhase(n);}
    public String details(){return benchmarkEnvironment();}
    public void checkpoint(String report){benchmarkReport=report;benchmarkRecommended=-1;prefs.edit().putString("benchmarkReport",report).putInt("benchmarkRecommended",-1).apply();}
    public void finished(String report,int ignored){checkpoint(report+"\nEstado final: "+benchmarkEnvironment());restoreBenchmark();changed();}
   };
   benchmark=capacityTest?new CapacityBenchmark(diagnosticDriver,fixedBuffer,context):new DiagnosticBenchmark(diagnosticDriver,fixedBuffer,context);
  }else{
  synth.panic();synth.automaticBuffer(false);synth.protectedOutput(true);synth.master=Math.min(.65f,synth.master);synth.wet=.3f;synth.setGains(new float[]{.28f,.28f,.28f,0});
  for(int ch=0;ch<3;ch++){synth.channels[ch]=PianoSoundPresets.apply(synth.channels[ch],3);synth.channels[ch].chorus=15;synth.channels[ch].repetition=35;}synth.change();
  int[] buffers=synth.activeBackend()>0?new int[]{8,6,4,2}:new int[]{32,16,12,8};String context=Build.MANUFACTURER+" "+Build.MODEL+" / Android "+Build.VERSION.RELEASE+"\nSaída: "+routeStatus+" / motor: "+Synth.backendName(synth.activeBackend())+" / polifonia "+synth.voiceLimit+"\nBancos: "+banks.get(selectedBank[0]).name+" · "+banks.get(selectedBank[1]).name+" · "+banks.get(selectedBank[2]).name;
  benchmark=new PianoBenchmark(new PianoBenchmark.Driver(){public void buffer(int ms){synth.latencyProfile(2);synth.manualBuffer(ms);synth.benchmarkMetrics();}public void midi(int type,int key,int value){synth.midi(type|synth.midiChannel,key,value);}public PianoBenchmark.Metrics metrics(){return synth.benchmarkMetrics();}public void finished(String report,int recommended){benchmarkReport=report;benchmarkRecommended=recommended;prefs.edit().putString("benchmarkReport",report).putInt("benchmarkRecommended",recommended).putString("benchmarkRoute",benchmarkRouteKey).apply();restoreBenchmark();changed();}},buffers,context);
  }
  benchmark.start(SystemClock.elapsedRealtime());main.removeCallbacks(benchmarkTick);main.post(benchmarkTick);changed();
 }
 private void restoreBenchmark(){main.removeCallbacks(benchmarkTick);if(benchmarkBefore==null)return;Scene before=benchmarkBefore;benchmarkBefore=null;synth.panic();synth.master=before.master;synth.wet=before.wet;synth.room=before.room;for(int ch=0;ch<4;ch++)synth.channels[ch]=before.effects[ch].copy();synth.latencyProfile(benchmarkProfile);synth.manualBuffer(benchmarkManual);synth.automaticBuffer(benchmarkAdaptive);synth.armSilent=benchmarkArm;synth.metro=benchmarkMetro;synth.soundEq=benchmarkEq;synth.soundChange();synth.protectedOutput(benchmarkProtect);applyMix();synth.change();savePreset(false);}
