 private final Runnable heartbeat=new Runnable(){public void run(){if(closed)return;
  long trafficNow=SystemClock.elapsedRealtime(),trafficTotal=midiBytes.get();if(midiTrafficAt>0&&trafficNow>midiTrafficAt){midiByteRate=(trafficTotal-midiBytesObserved)*1000.0/(trafficNow-midiTrafficAt);midiPeakRate=Math.max(midiPeakRate,midiByteRate);}midiBytesObserved=trafficTotal;midiTrafficAt=trafficNow;
  if(synth!=null){updateYamahaAudio();synth.collectTails();cleanup();if(capturing&&(!wav.active&&!wav.error.isEmpty()||!tape.warning.isEmpty()||!synth.isRunning())&&!cameraTake)finishTake(null);if(!connected()&&!synth.metro&&!tuner.active&&!captureBusy()&&!playingMidi&&synth.isRunning()&&SystemClock.elapsedRealtime()-lastUse>30000){synth.stop();setWake(false);routeStatus="Em espera · toque uma tecla de exemplo para retomar";}AudioDeviceInfo d=synth.routed();if(tuner.active){int id=d==null?-1:d.getId();if(id!=tunerRoute||synth.activeBackend()!=tunerEngine||!synth.isRunning()||loading)cancelTune();else{long nowTune=SystemClock.elapsedRealtime();if(noteCount>tuneNotes&&tuneFirstNote==0)tuneFirstNote=nowTune;boolean enoughPlaying=noteCount-tuneNotes>=4&&tuneFirstNote!=0&&nowTune-tuneFirstNote>=6000;int wanted=synth.underrunCount()>tuneFaults||enoughPlaying?tuner.observe(synth.underrunCount(),synth.acceptedBufferFrames(),nowTune):-1;if(wanted<0&&!enoughPlaying)tuner.status="Testando "+tuner.target+" ms · toque acordes repetidos por pelo menos 6 segundos.";if(wanted>=0){tuneNotes=noteCount;tuneFirstNote=0;tuneFaults=synth.underrunCount();synth.manualBuffer(wanted);if(!tuner.active){synth.automaticBuffer(true);saveAudio();}message=tuner.status;changed();}}}
   if(!synth.error.isEmpty()){routeStatus="Áudio interrompido: "+synth.error;setWake(false);}else if(synth.isRunning()&&d!=null)routeStatus=d.getProductName()+" · "+audioType(d.getType());}
  String text=connected()?midiStatus:reconnect.enabled()?"Aguardando piano · reconexão ativa":routeStatus;long now=SystemClock.elapsedRealtime();if(!text.equals(lastNotificationText)&&now-lastNotification>1500){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(4,notification(text));lastNotificationText=text;lastNotification=now;}
  main.postDelayed(this,synth!=null&&synth.isRunning()?500:3000);
 }};
