 public String diagnostic(){StringBuilder b=new StringBuilder("Piano Universe 0.27-preview1 / "+Build.MANUFACTURER+" "+Build.MODEL+" / Android "+Build.VERSION.RELEASE+"\n");b.append(midiStatus).append(String.format(java.util.Locale.US,"\nMIDI recebido: %.1f bytes/s · pico por intervalo %.1f bytes/s · total %d bytes\nTaxa de mensagens recebidas; velocidade física do cabo/USB não medida. Efeitos e pedal sustentado não aumentam o tamanho do fluxo de áudio USB.\n",midiByteRate,midiPeakRate,midiBytes.get())).append("\nSaída: ").append(routeStatus).append("\n").append(synth.diagnostic()).append("\n").append(synth.voiceDetails()).append("\nGravação: ").append(captureStatus).append("\nServiço em primeiro plano / reconexão ").append(reconnect.enabled()).append(" / CPU ativa ").append(wake.isHeld()).append("\n");for(int n=0;n<4;n++)if(!banks.isEmpty())b.append("Camada ").append(n+1).append(": ").append(banks.get(selectedBank[n]).name).append(" / timbre ").append(banks.get(selectedBank[n]).names[selectedPreset[n]]).append(" / pedal-biblioteca (custom,ms,keyCustom,ms) ").append(libraryPedal(selectedBank[n]).encode()).append(" / preset ").append(selectedPreset[n]).append(" / volume ").append(Math.round(synth.gain[n]*100)).append("%\n");b.append("Ressonância nativa: 88 notas / 264 modos / base A440 / perfil estimado opcional / sem fila adicional\n");for(int n=0;n<4;n++)b.append("Ressonância canal ").append(n+1).append(": ").append(synth.channels[n].resonance).append("% / chorus ").append(synth.channels[n].chorus).append(" / delay ").append(synth.channels[n].delay).append(" / feedback ").append(synth.channels[n].feedback).append(" / reverb ").append(synth.channels[n].reverb).append(" / pedal progressivo ").append(synth.channels[n].pedal).append(" / transição ").append(synth.channels[n].blend).append(" / contextual ").append(synth.channels[n].contextual).append(" / mecânica ").append(synth.channels[n].hammer).append("/").append(synth.channels[n].keyNoise).append("/").append(synth.channels[n].pedalNoise).append(" / ").append(pianoProfileStatus(n)).append(" / perfil ativo ").append(synth.channels[n].bankProfile).append("\n");for(int n=0;n<4;n++){ChannelSettings c=synth.channels[n];b.append("Corpo/tábua canal ").append(n+1).append(": ").append(c.bodyEnabled).append(" / corpo ").append(c.bodyAmount).append(" / tábua ").append(c.boardAmount).append(" / tamanho ").append(c.bodySize).append(" / amortecimento ").append(c.boardDamping).append(" / tampa ").append(c.lid).append(" / 16 modos / coloração reduzida / sem fila adicional\n");}for(int ch=0;ch<4;ch++){ChannelSettings c=synth.channels[ch];b.append("Ambiente canal ").append(ch+1).append(": híbrido ").append(c.hybrid).append(" / sala ").append(c.spaceRoom).append(" / ambiente ").append(c.ambience).append(" / textura ").append(c.texture).append(" / ducking ").append(c.ducking).append(" / cauda ").append(c.spaceDecay).append(" / repetição ").append(c.repetition).append(" / harmônicos ").append(c.harmonics).append(" / perfil v2 ").append(cachedPianoProfile(ch)!=null&&cachedPianoProfile(ch).length==792).append("\n");}b.append("Yamaha USB: ").append(yamahaAudioStatus).append(" / modo ").append(yamahaUsbMode).append(" / envio ").append(yamahaSend).append("% / loopback confirmado ").append(yamahaLoopbackOff).append("\n");b.append("Master ").append(Math.round(synth.master*100)).append("% / toque ").append(TouchResponse.NAMES[touchMode]).append(" / faixa ").append(touchLow).append("–").append(touchHigh).append(" / recebido ").append(rawVelocity).append(" → banco ").append(mappedVelocity).append("\nYamaha modo ").append(pianoMode).append(" / volume ").append(pianoVolume).append(" / integrado ").append(integrated).append("\n").append(remote.diagnostic()).append("\nÚltima câmera: ").append(prefs.getString("cameraDiagnostic","não utilizada")).append("\nImportação: ").append(lastImportReport());return b.toString();}
 private void endSession(){if(closed)return;pauseYamahaAudio();stopBenchmark("Sessão encerrada.");closed=true;stopMidi();releasePlayer();tape.stop();wav.finish();if(capturing&&takeMidi!=null){File pending=takeMidi;worker.execute(()->{try{tape.save(pending);}catch(IOException ignored){}});}capturing=false;preparingTake=false;finishingTake=false;main.removeCallbacksAndMessages(null);reconnect.disable();if(manager!=null&&parser!=null)manager.unregisterDeviceCallback(midiCallback);if(audio!=null&&parser!=null)audio.unregisterAudioDeviceCallback(audioCallback);closeMidi(true);if(synth!=null){Synth.retroEnable(false);synth.close();}setWake(false);if(audio!=null&&focusRequest!=null)audio.abandonAudioFocusRequest(focusRequest);worker.execute(()->{for(Bank bank:banks)free(bank);});worker.shutdown();captureStatus="Sessão encerrada; arquivos de áudio/MIDI preservados.";completeTakeCallbacks();}
 @Override public void onDestroy(){stopBenchmark("Sessão encerrada.");endSession();super.onDestroy();}
